import json, os
for base_name in ['plan_c', 'backbone_72b']:
    base = '/root/autodl-tmp/simgate-modular-routing/results/' + base_name
    for t in sorted(os.listdir(base)):
        f = os.path.join(base, t, 'episodes.jsonl')
        if not os.path.isfile(f):
            continue
        total = 0
        bad = 0
        with open(f) as fh:
            for line in fh:
                total += 1
                ep = json.loads(line)
                if 'always_internal' not in ep:
                    bad += 1
        if bad > 0:
            print('%s/%s: %d/%d lines missing always_internal' % (base_name, t, bad, total))
    print('%s: check done' % base_name)
"
